import React, { useEffect } from 'react'
import * as Yup from "yup";
import { useFormik } from "formik";
import { CustomForm, CustomFormItem, CustomInput } from '../../../components'
import { Modal } from 'antd';
import { toast, ToastContainer } from 'react-toastify';
import { useStateContext } from '../../../contexts/ContextProvider';
import { Button } from '@heroui/react';
import useApi from '../../../hooks/useApi';
import retailersApi from '../../../api/retailers/retailersApi';

export default function RetailIndentFormModal({ isIndentModalOpen, setisIndentModalOpen, openIndent,setopenIndent,errors,setErrors }) {
    const { currentColor } = useStateContext()


    const createRetailerIndentApi = useApi(retailersApi.retailerOrdersStaffAction)
    const createRetailerIndent=async(data)=>{
        await createRetailerIndentApi.request(data)
    }


    useEffect(()=>{
        if(createRetailerIndentApi.data){
            if(createRetailerIndentApi.data.retailer_indent){
                setisIndentModalOpen(false)
                setopenIndent(createRetailerIndentApi.data.retailer_indent)
                toast.success(createRetailerIndentApi.data.response_message)
            }

            if(createRetailerIndentApi.data.errors){
               
                setErrors(createRetailerIndentApi.data.errors)
              
            }
        }
        console.log("createRetailerIndentApi.data",createRetailerIndentApi.data)
    },[createRetailerIndentApi.data])
    const formik = useFormik({
        initialValues: {
            "order_days": "",
            "lead_time": ""
        },

        validationSchema: Yup.object({
            order_days: Yup.number().min(1).required("Order days is required"),
            lead_time: Yup.number().min(1).required("Lead time is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);

            const data ={

                "action":"CreateRetailerIndent",
                "order_days":values.order_days,
                "lead_time":values.lead_time
            }

            createRetailerIndent(data)



            // resetForm();
        },
    });
    const handleOk = () => {
        setisIndentModalOpen(false);
    };
    const handleCancel = () => {
        setisIndentModalOpen(false);
    };

    return (
        <div className="w-full">
            <Modal
                width={600}
                className="w-full text-center"
                title={
                    openIndent ? "Update Indent" : "Create Indent"
                }
                open={isIndentModalOpen}
                onOk={handleOk}
                onCancel={handleCancel}
                closeIcon={true}
                closable={false}
                cancelButtonProps={{ style: { display: "none" } }}
                okButtonProps={{ style: { display: "none" } }}
            >
                <ToastContainer theme="colored" position="bottom-center" />
                <CustomForm
                    layout="vertical"
                    handleFinish={formik.handleSubmit}
                    className=" flex flex-col justify-center items-center w-full"
                >
                    <CustomFormItem
                        touched={formik.touched.order_days}
                        error={formik.errors.order_days}
                    >
                        <CustomInput
                            required={true}
                            id="order_days"
                            name="order_days"
                            onChange={formik.handleChange}
                            placeholder="Enter number of order days"
                            size="large"
                            type="number"
                            value={
                                formik.values.house_allowance
                            }
                            label="Enter number of order days"
                        />
                    </CustomFormItem>

                    <CustomFormItem
                        touched={formik.touched.lead_time}
                        error={formik.errors.lead_time}
                    >
                        <CustomInput
                            required={true}
                            id="lead_time"
                            name="lead_time"
                            onChange={formik.handleChange}
                            placeholder="Enter lead time in days"
                            size="large"
                            type="number"
                            value={
                                formik.values.lead_time
                            }
                            label="Enter number of order days"
                        />
                    </CustomFormItem>

                    <div className="w-full items-center mt-2">
                        <Button
                            style={{ background: currentColor, color: 'white' }}
                            className="w-36 rounded-md text-wrap"
                            color="primary"
                            type="submit"
                        >
                            Submit
                        </Button>
                    </div>
                </CustomForm>
            </Modal>
        </div>
    )
}
