import React, { useEffect, useRef, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import useApi from "../../../hooks/useApi";
import employeesApi from "../../../api/employees/employeesApi";
import { BsTrash } from "react-icons/bs";
import retailersApi from '../../../api/retailers/retailersApi'

import {
  createRetailerOrderItem,
  retrieveDraftRetailerOrders,
  updateOrderItems,
  removeOrderItem,
  updateOtherOrderDetails,
  deleteDraftOrder,
  updateOrderItemDiscount,
  updateOrderItemQuantity,
} from "../../../helpers/wholesalerHelpers";
import {
  Avatar,
  Card,
  CardFooter,
  CardHeader,
  CardBody,
  Input,
  Divider,
  Tab,
  Tabs,
  RadioGroup,
  ButtonGroup,
} from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomRadioItem,
  DeleteIcon,
  Loading,
  PlusIcon,
  SearchIcon,
} from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import useScreenSize from "../../../hooks/useScreenSize";
import { ToastContainer, toast } from "react-toastify";
import paymentsApi from "../../../api/paymentsApi";
import { Button } from "@heroui/react";
import { useDispatch, useSelector } from "react-redux";
import { getRetailerReceipts } from "../../../redux/retailers/receipts/actions";
import "react-toastify/dist/ReactToastify.css";
import { CardTitle } from "reactstrap";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import CarouselQuantityDiscounts from "./CarouselQuantityDiscounts";
import wholesalersApi from "../../../api/wholesalers/wholesalersApi";

import CarouselPriceDiscounts from "./CarouselPriceDiscounts";
import RequiredIndentQuantityFormModal from "./RequiredIndentQuantityFormModal ";
import RetailIndentFormModal from "./RetailIndentFormModal";
import WholesalerReceiptCard from "./WholesalerReceiptCard";


function DraftRetailerOrderCart() {
  const [selected, setSelected] = React.useState("products");
  const screenSize = useScreenSize();
  const { dangerColor } = useStateContext();
  const [openIndent, setopenIndent] = useState()
  const [isIndentModalOpen, setisIndentModalOpen] = useState(false)


  // const { draft_id } = useParams();
  const { state } = useLocation();
  const { id } = useParams();
  console.log("DI", state);
  const dispatch = useDispatch();
  const [reference, setReference] = useState();
  const [employeeId, setemployeeId] = useState();
  const [data, setdata] = useState([]);
  const [errors, setErrors] = useState([]);
  const { currentColor, successColor, loggedInUser } = useStateContext();
  console.log("loggedInUser", loggedInUser);
  const [authorizationModalOpen, setauthorizationModalOpen] = useState(false);
  const [showJPAuthDialog, setshowJPAuthDialog] = useState(false);

  const [openShippingAddressModal, setopenShippingAddressModal] =
    useState(false);
  const [shippingDetails, setshippingDetails] = useState();

  const [openMpesaNumberModal, setopenMpesaNumberModal] = useState(false);
  const [mpesaNumber, setmpesaNumber] = useState();

  const [openCashpaymentModal, setopenCashpaymentModal] = useState(false);
  const [selectedIndent, setselectedIndent] = useState();

  const [updated, setUpdated] = useState(false);

  const [openCounterDiscountDialog, setopenCounterDiscountDialog] =
    useState(false);
  const [counterDiscount, setcounterDiscount] = useState();
  const [selectedOrder, setselectedOrder] = useState();
  const [currentEmploymentDetails, setcurrentEmploymentDetails] = useState();
  const [draftRetailerOrders, setdraftRetailerOrders] = useState([]);
  const [openRequiredQuantityModal, setopenRequiredQuantityModal] =
    useState(false);
  const [wholesalerReceipts, setWholesalerReceipts] = useState([]);
  const [quantity, setQuantity] = useState();
  const [selectedWholesalerReceipt, setselectedWholesalerReceipt] = useState();
  const [selectedWholesalerReceiptId, setselectedWholesalerReceiptId] = useState();
  const [selectedOrderItems, setselectedOrderItems] = useState([]);
  const [draftId, setdraftId] = useState(state.draft_id);
  const [selectedPaymentMethod, setselectedPaymentMethod] = useState(
    selectedOrder && selectedOrder.payment_method
      ? selectedOrder.payment_method
      : ""
  );
  const [selectedDeliveryOption, setselectedDeliveryOption] = useState(
    selectedOrder && selectedOrder.delivery_method
      ? selectedOrder.delivery_method
      : ""
  );
  const [orderTotal, setorderTotal] = useState();
  const [cashbalance, setcashbalance] = useState(0);
  const [tenderedAmount, settenderedAmount] = useState();
  const [selectedOrderItem, setselectedOrderItem] = useState();





  const navigate = useNavigate();
  const getDraftOrders = async () => {
    const drafts = await retrieveDraftRetailerOrders(state.wholesaler_id);

    console.log("retrieved drafts", drafts);

    if (drafts) {
      setdraftRetailerOrders(drafts);
    }
  };

  //Retrieve employment details
  const getCurrentEmploymentDetailsApi = useApi(
    employeesApi.employeesActionJoint
  );
  const getCurrentEmploymentDetails = async () => {
    await getCurrentEmploymentDetailsApi.request({
      action: "CurrentUserEmployment",
    });
  };

  useEffect(() => {
    if (getCurrentEmploymentDetailsApi.data) {
      if (getCurrentEmploymentDetailsApi.data.employee) {
        setemployeeId(getCurrentEmploymentDetailsApi.data.employee.id);
        setcurrentEmploymentDetails(
          getCurrentEmploymentDetailsApi.data.employee
        );
      }
    }

    console.log(
      "getCurrentEmploymentDetailsApi.data",
      getCurrentEmploymentDetailsApi.data
    );
  }, [getCurrentEmploymentDetailsApi.data]);

  useEffect(() => {
    getDraftOrders();
    getCurrentEmploymentDetails();
  }, []);

  //Set selected order
  useEffect(() => {
    if (draftRetailerOrders.length) {
      setselectedOrder(draftRetailerOrders.find((x) => x.draft_id === draftId));
    }
  }, [draftRetailerOrders]);

  //Retrieve retailer receipts
  const wholesalerReceiptsActionsApi = useApi(
    wholesalersApi.wholesaleReceiptsAction
  );

  const getTotalValue = (items) => {
    let totalValue = 0.0;
    for (let x of items) {
      totalValue += x.required_quantity * x.final_pack_price;
    }

    return totalValue;
  };

  const closeRetailerIndentApi = useApi(retailersApi.retailerOrdersStaffAction)
  const handleCloseIndent = async () => {
    if (!openIndent) {
      toast.error("No open indent to close");
      return;
    }
    await closeRetailerIndentApi.request({

      "action": "CloseRetailerIndent",
      "indent": openIndent.id
    })
  };


  useEffect(() => {
    if (closeRetailerIndentApi.data) {

      if (closeRetailerIndentApi.data.retailer_indent) {
        setopenIndent(closeRetailerIndentApi.data.retailer_indent)
        toast.success(closeRetailerIndentApi.data.response_message)
        setopenIndent(null)
      } else {
        toast.error(closeRetailerIndentApi.data.response_message)
      }
    }
    console.log("closeRetailerIndentApi.data", closeRetailerIndentApi.data)
  }, [closeRetailerIndentApi.data])


  const getWholesalerReceipts = async (ide) => {
    setWholesalerReceipts([]);
    await wholesalerReceiptsActionsApi.request({
      action: "GetWholesalerReceiptsWithAnalytics",
      order_days: 30,
      wholesaler_id: ide,
      retailer_id: loggedInUser.entity_id,
    });
  };

  useEffect(() => {
    if (
      wholesalerReceiptsActionsApi.data &&
      wholesalerReceiptsActionsApi.data.length
    ) {
      setWholesalerReceipts(wholesalerReceiptsActionsApi.data);
    }

    console.log(
      "wholesalerReceiptsActionsApi.data",
      wholesalerReceiptsActionsApi.data
    );
  }, [wholesalerReceiptsActionsApi.data]);

  //Retrieve reference numbers

  const [selectedWholesalerId, setselectedWholesalerId] = useState(state.id)
  useEffect(() => {
    if (selectedWholesalerId) {
      getWholesalerReceipts(selectedWholesalerId);
      getPriceDiscounts(selectedWholesalerId)
      getQuantityDiscounts(selectedWholesalerId)
    }

  }, [selectedWholesalerId]);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      dispatch(getRetailerReceipts({ action: "GetRetailerReceipts" }));
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 200000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled]);

  //Selected delivery method
  useEffect(() => {
    if (selectedDeliveryOption) {
      if (selectedDeliveryOption && selectedDeliveryOption === "DELIVERY") {
        //Open shipping details modal
        setopenShippingAddressModal(true);
      } else {
        //Close shipping details modal
        setopenShippingAddressModal(false);
      }

      //Update order delivery option
      setselectedOrder(
        updateOtherOrderDetails(selectedOrder && selectedOrder.draft_id, {
          delivery_method: selectedDeliveryOption,
        })
      );
    }
  }, [selectedDeliveryOption]);

  useEffect(() => {
    if (selectedPaymentMethod) {
      if (selectedPaymentMethod && selectedPaymentMethod === "MOBILE MONEY") {
        setopenMpesaNumberModal(true);
      } else {
        setopenMpesaNumberModal(false);
      }

      if (selectedPaymentMethod && selectedPaymentMethod === "CASH") {
        setorderTotal(
          selectedOrderItems &&
          selectedOrderItems
            .reduce((acc, item) => acc + item.item_price_total, 0)
            .toFixed(2)
        );
        setopenCashpaymentModal(true);
      } else {
        setopenCashpaymentModal(false);
      }
    }
  }, [selectedPaymentMethod]);

  useEffect(() => {
    setdata(wholesalerReceipts);
  }, [wholesalerReceipts]);

  const handleFilter = (e) => {
    const search_param = e.target.value;

    if (
      wholesalerReceipts &&
      wholesalerReceipts.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        wholesalerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(wholesalerReceipts);
    }
  };

  //Retrieve payment methods
  const [paymentMethods, setpaymentMethods] = useState([]);
  const paymentMethodsActionsApi = useApi(
    paymentsApi.allowePaymentMethodsAction
  );

  const getPaymentMethods = async (data) => {
    await paymentMethodsActionsApi.request(data);
  };

  useEffect(() => {
    getPaymentMethods({
      action: "GetCashlessPaymentMethods",
    });
  }, []);
  useEffect(() => {
    if (paymentMethodsActionsApi.data && paymentMethodsActionsApi.data.length) {
      setpaymentMethods(paymentMethodsActionsApi.data);
    }

    console.log("paymentMethodsActionsApi.data", paymentMethodsActionsApi.data);
  }, [paymentMethodsActionsApi.data]);

  //Add item to cart
  const handleAddToIndent = (item) => {

    setopenRequiredQuantityModal(true);
    setselectedWholesalerReceipt(item);
    setUpdated(false);
  };

  //Create order item
  useEffect(() => {
    if (quantity && selectedWholesalerReceipt) {
      const retailerOrderItem = createRetailerOrderItem(
        draftId,
        parseInt(quantity),
        selectedWholesalerReceipt
      );
      console.log("Create ROI", retailerOrderItem);

      const currentOrderItems = selectedOrderItems;
      console.log("item c", currentOrderItems);

      if (selectedOrderItems && selectedOrderItems.length > 0) {
        const exists = selectedOrderItems.find(
          (x) => x.wholesaler_receipt === retailerOrderItem.wholesaler_receipt
        );
        if (exists) {
          console.log("Iko");
          const without = currentOrderItems.filter(
            (x) => x.wholesaler_receipt !== retailerOrderItem.wholesaler_receipt
          );
          setselectedOrderItems([...without, retailerOrderItem]);
        } else {
          setselectedOrderItems([...currentOrderItems, retailerOrderItem]);
          console.log("Hakuna");
        }
      } else {
        setselectedOrderItems([retailerOrderItem]);
      }
    }
  }, [quantity, selectedWholesalerReceipt, openRequiredQuantityModal]);

  useEffect(() => {
    if (counterDiscount != undefined) {
      setselectedOrder(
        updateOrderItemDiscount(
          selectedOrder.draft_id,
          counterDiscount,
          selectedOrderItem
        )
      );
    }
  }, [counterDiscount]);

  const retailerOrderActionsApi = useApi(
    wholesalersApi.wholesaleRetailersAction
  );

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
    console.log("errors", errors);
  }, [errors]);

  useEffect(() => {
    if (retailerOrderActionsApi.data) {
      if (retailerOrderActionsApi.data.errors) {
        setErrors(retailerOrderActionsApi.data.errors);
        toast.error(retailerOrderActionsApi.data.response_message);
      } else {
        toast.success(retailerOrderActionsApi.data.response_message);
      }
    }
    console.log("errors", errors);
    console.log("retailerOrderActionsApi.data", retailerOrderActionsApi.data);
  }, [retailerOrderActionsApi.data]);

  const saveDraftCustomerOrder = async (data) => {
    const result = await retailerOrderActionsApi.request(data);
    console.log("res at create order", result);
    if (result.ok) {
      setReference(result.data.reference);
      setauthorizationModalOpen(true);

      deleteDraftOrder(selectedOrder.draft_id);
      navigate(`/marketplace/wholesaler/home/${selectedOrder.wholesaler}`, {
        state: {
          id: selectedOrder.wholesaler,
          title: selectedOrder.wholesaler_title,
        },
      });
    } else {
      setErrors(result.data.errors);
    }
  };
  const handleCloseOrder = () => {
    if (!selectedOrder) {
      toast.error("Order is not created");
      return;
    }
    if (!selectedPaymentMethod) {
      toast.error("Select payment method");
    } else {
      console.log("Selected order", selectedOrder);
      console.log("selectedOrderItems", selectedOrderItems);

      let orderItemsArr = [];
      selectedOrderItems.map((item) =>
        orderItemsArr.push({
          purchased_quantity: item.required_quantity,
          wholesaler_receipt_id: item.wholesaler_receipt,
        })
      );
      console.log("orderItemsArr", orderItemsArr);

      // const data = {
      //   action: "CreateCustomerOrder",
      //   customer_order_details: {
      //     payment_method_id: selectedOrder.payment_method,
      //     order_type: selectedOrder.order_type,
      //     payment_account_number: formatKenyaPhoneNumber(mpesaNumber),
      //     order_origin: "STAFF",
      //     customer_id: "",
      //     customer_name: selectedOrder.customer_name,
      //     customer_phone: selectedOrder.customer_phone,
      //     employee_id: employeeId,
      //     order_items: selectedOrder.orderItems,
      //     reference_number: selectedOrder.reference_number,
      //   },
      // };
      const data = {
        action: "CreateRetailerOrder",
        retailer_order_details: {
          wholesaler_id: selectedOrder.wholesaler,
          order_terms: "CASH",
          order_type: "NORMAL",
          order_origin: "RETAILER",
          payment_method_id: selectedOrder.payment_method,
          payment_account_number: mpesaNumber,
          retailer_order_items: orderItemsArr,
        },
      };
      saveDraftCustomerOrder(data);
      if (selectedOrder.payment_method_title === "JAMBOPAY WALLET") {
        setshowJPAuthDialog(true);
      }

      console.log("order data", data);
    }
  };

  // const handleUpdateCounterDiscount = (item) => {
  //   setselectedOrderItem(item);
  //   setopenCounterDiscountDialog(true);
  // };

  // const handleEditItemQuantity = (item) => {
  //   setselectedOrderItem(item);
  //   setopenRequiredQuantityModal(true);
  // };

  useEffect(() => {
    if (updated === true) getOpenIndent();
  }, [updated]);

  useEffect(() => {
    if (quantity && selectedOrderItem) {
      setselectedOrder(
        updateOrderItemQuantity(
          selectedOrder.draft_id,
          quantity,
          selectedOrderItem.wholesaler_receipt
        )
      );
      setselectedOrderItem(null);
    }
    console.log("qty", quantity);
  }, [quantity]);

  const wholesalerPriceDiscountsApi = useApi(
    wholesalersApi.wholesaleReceiptsAction
  );
  const [priceDiscounts, setpriceDiscounts] = useState([]);

  const getPriceDiscounts = async (ide) => {
    await wholesalerPriceDiscountsApi.request({
      action: "WholesalerPriceDiscountsById",
      wholesaler: ide,
    });
  };

  useEffect(() => {
    if (
      wholesalerPriceDiscountsApi.data &&
      wholesalerPriceDiscountsApi.data.length
    ) {
      setpriceDiscounts(wholesalerPriceDiscountsApi.data);
    }
    console.log(
      "wholesalerPriceDiscountsApi.data",
      wholesalerPriceDiscountsApi.data
    );
  }, [wholesalerPriceDiscountsApi.data]);



  const wholesalerQuantityDiscountsApi = useApi(
    wholesalersApi.wholesaleReceiptsAction
  );
  const [quantityDiscounts, setquantityDiscounts] = useState([]);
  const getQuantityDiscounts = async (ide) => {
    await wholesalerQuantityDiscountsApi.request({
      action: "WholesalerQuantityDiscountsById",
      wholesaler: ide,
    });
  };

  useEffect(() => {
    if (
      wholesalerQuantityDiscountsApi.data &&
      wholesalerQuantityDiscountsApi.data.length
    ) {
      setquantityDiscounts(wholesalerQuantityDiscountsApi.data);
    }
    console.log(
      "wholesalerQuantityDiscountsApi.data",
      wholesalerQuantityDiscountsApi.data
    );
  }, [wholesalerQuantityDiscountsApi.data]);











  const getOpenIndentApi = useApi(retailersApi.retailerOrdersStaffAction);

  const getOpenIndent = async () => {
    await getOpenIndentApi.request({
      action: "RetrieveCurrentOpenIndent",
    });
  };

  useEffect(() => {
    getOpenIndent();
  }, []);

  useEffect(() => {
    console.log("getOpenIndentApi.data", getOpenIndentApi.data);
    if (getOpenIndentApi.data) {
      if (getOpenIndentApi.data.indent) {
        setselectedIndent(getOpenIndentApi.data.indent);
        setopenIndent(getOpenIndentApi.data.indent)
        toast.success(getOpenIndentApi.data.response_message)
      } else {
        setisIndentModalOpen(true)
        toast.error(getOpenIndentApi.data.response_message)
      }
    }
    console.log("getOpenIndentApi.data", getOpenIndentApi.data)
  }, [getOpenIndentApi.data]);

  const removeItemApi = useApi(retailersApi.retailerOrdersStaffAction);

  const handleRemoveFromIndent = async (item) => {
    console.log("Item", item);
    const data = {
      action: "RemoveRetailerIndentItem",
      retailer_indent: item.retailer_indent,
      retailer_indent_item: item.id,
    };

    await removeItemApi.request(data);
  };

  useEffect(() => {
    console.log("removeItemApi.data", removeItemApi.data);

    getOpenIndent();
  }, [removeItemApi.data]);

  const columns = [
    {
      title: "Names",
      dataIndex: "dependant_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Date of Birth",
      dataIndex: "dependant_dob",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Age",
      dataIndex: "dependant_age",
    },
    {
      title: "Gender",
      dataIndex: "dependant_gender",
    },
    {
      title: "Department",
      dataIndex: "department_title",
    },
    {
      title: "Time In",
      dataIndex: "checkin_time",
    },
    {
      title: "Time Out",
      dataIndex: "checkout_time",
    },
  ];


  const [selectedInventoryItem, setselectedInventoryItem] = useState()
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);

  const onSelectChange = (newSelectedRowKeys, selectedRows) => {
    console.log("selectedRowKeys changed: ", newSelectedRowKeys);
    setSelectedRowKeys(newSelectedRowKeys);
    selectedInventoryItem(selectedRows[0]);
  };

  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  useEffect(() => {
    if (selectedRowKeys && selectedRowKeys.length === 1) {

    } else {
      return;
    }
  }, [selectedRowKeys]);


  const wholesalerRececeiptDetailsApi = useApi(wholesalersApi.wholesaleReceiptsAction)

  const getWholesalerReceiptDetails = async (selectedWholesalerReceiptId) => {

    await wholesalerRececeiptDetailsApi.request({
      "action": "GetWholesaleReceiptDetails",
      "id": selectedWholesalerReceiptId
    })

  }

  useEffect(() => {
    if (selectedWholesalerReceiptId) {
      getWholesalerReceiptDetails(selectedWholesalerReceiptId)
    }
  }, [selectedWholesalerReceiptId]);

  useEffect(() => {
    if (wholesalerRececeiptDetailsApi.data && wholesalerRececeiptDetailsApi.data.wholesale_receipt !== null) {
      setselectedWholesalerReceipt(wholesalerRececeiptDetailsApi.data.wholesale_receipt)
      setopenRequiredQuantityModal(true)
    }
  }, [wholesalerRececeiptDetailsApi.data]);


  return (
    <div className="m-auto min-h-screen grid grid-cols-12 mt-14 md:mt-1 w- bg-gray-200 ">
      <div className="col-span-1"></div>
      <div className="col-span-10 w-full">
        <div className="flex justify-center items-center my-1">

          <Card isPressable
            className="shadow-md rounded-md w-full  max-h-36"

          >

            <CardHeader className="justify-around ">

              <Avatar isBordered
                radius="full"
                size="lg"
                src="https://heroui.com/avatars/avatar-1.png" />

              <div className="flex flex-col gap-1 items-start justify-start mx-2">
                <h4 className="text-medium font-semibold leading-none text-default-600 uppercase">{state.title}</h4>

              </div>
            </CardHeader>

          </Card>
        </div>
        <div className="grid md:grid-cols-2 gap-x-6 px-2 py-1 grid-cols-1 bg-gray-100 min-h-[450px] max-h-[450px]  md:min-h-[450px] mt-1">





          <div>          {quantityDiscounts && quantityDiscounts.length ? (
            <div className=" max-h-[450px] mx-2 rounded-sm px-2 ">

              <CarouselQuantityDiscounts
                quantityDiscounts={quantityDiscounts}
                slidesToScroll={2}
                slidesToShow={2}
                setopenRequiredQuantityModal={setopenRequiredQuantityModal}
                setselectedWholesalerReceiptId={setselectedWholesalerReceiptId}
              />

            </div>
          ) : (
            <div></div>
          )}</div>

          <div>          {priceDiscounts && priceDiscounts.length ? (
            <div className=" max-h-[450px] mx-2 rounded-sm px-2 ">

              <CarouselPriceDiscounts
                priceDiscounts={priceDiscounts}
                slidesToScroll={3}
                slidesToShow={3}
                setopenRequiredQuantityModal={setopenRequiredQuantityModal}
                setselectedWholesalerReceiptId={setselectedWholesalerReceiptId}
              />

            </div>
          ) : (
            <div></div>
          )}</div>

        </div>
        <div className="grid grid-cols-12">

          <RetailIndentFormModal isIndentModalOpen={isIndentModalOpen} setisIndentModalOpen={setisIndentModalOpen} openIndent={openIndent} setopenIndent={setopenIndent} errors={errors} setErrors={setErrors} />
        </div>
        {screenSize.width < 768 ? (
          <div>
            <Card className="max-w-full">
              <ToastContainer position="bottom-center" theme="colored" />
              <CardBody className="overflow-hidden">
                <Tabs
                  fullWidth
                  size="md"
                  aria-label="Tabs form"
                  selectedKey={selected}
                  onSelectionChange={setSelected}
                >
                  <Tab key="products" title="Products">
                    <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
                      <h1 className="text-large font-bold text-center">
                        Products List
                      </h1>
                      {getOpenIndentApi.loading ? (
                        <Loading loading={getOpenIndentApi.loading} />
                      ) : (
                        <Card className="max-w-full mx-1 md:mx-5 my-1 rounded-none">
                          <CardBody>
                            <Input
                              label="Search"
                              isClearable
                              radius="lg"
                              onChange={(e) => handleFilter(e)}
                              classNames={{
                                label: "text-black/50 dark:text-white/90",
                                input: [
                                  "bg-transparent",
                                  "text-black/90 dark:text-white/90",
                                  "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                ],
                                innerWrapper: "bg-transparent",
                                inputWrapper: [
                                  "shadow-xl",
                                  "bg-default-200/50",
                                  "dark:bg-default/60",
                                  "backdrop-blur-xl",
                                  "backdrop-saturate-200",
                                  "hover:bg-default-200/70",
                                  "dark:hover:bg-default/70",
                                  "group-data-[focused=true]:bg-default-200/50",
                                  "dark:group-data-[focused=true]:bg-default/60",
                                  "!cursor-text",
                                ],
                              }}
                              placeholder="Type to search..."
                              startContent={
                                <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                              }
                            />
                          </CardBody>
                        </Card>
                      )}
                      {data &&
                        data.length > 0 &&
                        data.map((item) => (
                          <WholesalerReceiptCard onClick={() => handleAddToIndent(item)} item={item} selectedOrder={selectedOrder} />
                        ))}
                    </div>
                  </Tab>
                  <Tab key="cart" title="Customer Order">
                    {selectedIndent ? (
                      <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
                        <Card className="max-w-full mx-1 md:mx-5 my-1 rounded-sm">
                          <CardHeader>
                            <CardTitle className="font-bold text-lg">
                              Indent Summary
                            </CardTitle>
                          </CardHeader>
                          <CardBody>
                            <div className="grid grid-cols-2 md:grid-cols-4">
                              <div>
                                <p className="text-slate-500">Items</p>
                                <p className="font-bold text-gray-400">
                                  {selectedIndent &&
                                    selectedIndent.retailer_indent_items
                                    ? selectedIndent.retailer_indent_items.length
                                    : 0}
                                </p>
                              </div>
                              <div>
                                <p className="text-slate-500">Order Days</p>
                                <p className="font-bold text-gray-400">
                                  {selectedIndent.order_days}
                                </p>
                              </div>
                              <div>
                                <p className="text-slate-500">Lead Time</p>
                                <p className="font-bold text-gray-400">
                                  {selectedIndent.lead_time}
                                </p>
                              </div>
                              <div>
                                <p className="text-slate-500">Is Open</p>
                                <p className="font-bold text-gray-400 uppercase">
                                  {selectedIndent.is_open}
                                </p>
                              </div>
                            </div>
                          </CardBody>
                        </Card>
                        {selectedIndent &&
                          selectedIndent.retailer_indent_items &&
                          selectedIndent.retailer_indent_items.map((item) => (
                            <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                              <CardHeader className="justify-between">
                                <div className="flex gap-5 items-center mx-2 justify-between w-full">
                                  <Avatar
                                    className="w-20 h-20 text-large"
                                    size="lg"
                                    src={
                                      item.images && item.images[0]
                                        ? item.images[0].image
                                        : ""
                                    }
                                    name={item.wholesale_receipt_title}
                                  />
                                  <div className="flex flex-col items-start justify-center w-full">
                                    <h4 className="text-medium font-semibold leading-none text-default-600">
                                      {item.wholesale_receipt_title}
                                    </h4>
                                    <p className="text-medium tracking-tight text-default-400">
                                      {item.wholesaler_title}
                                    </p>

                                    <div className="flex flex-row justify-between w-full">
                                      <p className="text-medium tracking-tight text-default-400">
                                        KES {item.pack_selling_price}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 ">
                                        Qty Required: {item.required_quantity}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 text-start ">
                                        Discount:{" "}
                                        {item.price_discount_title
                                          ? item.price_discount_title
                                          : "None"}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 text-start">
                                        Net: KES {item.final_pack_price}
                                      </p>
                                    </div>
                                    <div className="flex flex-row justify-between w-full">
                                      <div className="flex flex-row justify-between">
                                        {item.days_to_expiry &&
                                          item.days_to_expiry < 90 ? (
                                          <h6 className="text-medium tracking-tight text-red-600 pr-3">
                                            Expiry Date:{" "}
                                            {item.expiry_date
                                              ? item.expiry_date
                                              : "Not Indicated"}
                                          </h6>
                                        ) : (
                                          <h6 className="text-medium tracking-tight text-green-600">
                                            Expiry Date:{" "}
                                            {item.expiry_date
                                              ? item.expiry_date
                                              : "Not indicated"}
                                          </h6>
                                        )}
                                        {item.days_to_expiry &&
                                          item.days_to_expiry < 90 ? (
                                          <h6 className="text-medium tracking-tight text-red-600 pl-3">
                                            {item.expiry_status}
                                          </h6>
                                        ) : (
                                          <h6 className="text-medium tracking-tight text-green-600">
                                            {item.expiry_status}
                                          </h6>
                                        )}
                                      </div>
                                      <div>
                                        <BsTrash
                                          onClick={() =>
                                            handleRemoveFromIndent(item)
                                          }
                                          className="cursor-pointer hover:resize-x"
                                          size={36}
                                          color={dangerColor}
                                        />
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              </CardHeader>
                            </Card>
                          ))}

                        <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                          <CardBody>
                            <div>
                              <p>INDENT VALUE</p>
                              <p>
                                {" "}
                                KES{" "}
                                {parseFloat(
                                  getTotalValue(
                                    selectedIndent.retailer_indent_items
                                  )
                                ).toFixed(2)}
                              </p>
                            </div>
                          </CardBody>
                        </Card>
                        {selectedIndent.is_open === "true" ? (
                          <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                            <Button
                              style={{ background: currentColor, color: "white" }}
                              size="lg"
                              radius="none"
                              text="Close Indent"
                              onPress={() => handleCloseIndent()}
                              className="m-1"
                            >
                              Close Indent
                            </Button>
                          </Card>
                        ) : (
                          <div></div>
                        )}
                      </div>
                    ) : (
                      <div></div>
                    )}
                  </Tab>
                </Tabs>
              </CardBody>
            </Card>
          </div>
        ) : (
            <div className="grid md:grid-cols-2 gap-6 mt-1">
              {getOpenIndentApi.loading ? (
                <Loading loading={getOpenIndentApi.loading} />
              ) : (
                <div className="max-h-[720px] bg-gray-100 overflow-y-scroll my-10">
                  <ToastContainer position="bottom-center" theme="colored" />
                  <h1 className="text-large font-bold text-center">
                    Products List
                  </h1>

                    <div className="w-full px-2">
                      <CustomInput
                        className="uppercase w-full h-14 text-lg"
                        required={false}
                        label="Filter by product name"
                        id="charge"
                        name="charge"
                        onChange={(e) => console.log(e.target.value)}
                        placeholder="Filter by product name"
                        size="large"
                        type="text"

                      />

                    </div>
                    {data && data.length > 0 ? (
                      data.map((item) => (
                        <WholesalerReceiptCard onClick={() => handleAddToIndent(item)} item={item} selectedOrder={selectedOrder} />
                      ))
                    ) : (
                      <div className="h-screen m-auto">No products to display</div>
                    )}


                    {openRequiredQuantityModal && selectedIndent && selectedWholesalerReceipt && (
                    <RequiredIndentQuantityFormModal
                      openEditModal={openRequiredQuantityModal}
                      setopenEditModal={setopenRequiredQuantityModal}
                      quantity={quantity}
                      selectedWholesalerReceipt={selectedWholesalerReceipt}
                      setQuantity={setQuantity}
                      retailerIndent={selectedIndent}
                      updated={updated}
                      setUpdated={setUpdated}
                    />
                  )}
                </div>
              )}
              {selectedIndent ? (
                <div className="max-h-[720px] bg-gray-100 overflow-y-scroll my-10">
                  <Card className="max-w-full mx-1 md:mx-5 my-1">
                    <CardHeader>
                      <CardTitle className="font-bold text-lg">
                        Indent Summary
                      </CardTitle>
                    </CardHeader>
                    <CardBody>
                      <div className="grid grid-cols-2 md:grid-cols-4">
                        <div>
                          <p className="text-slate-500">Items</p>
                          <p className="font-bold text-gray-400">
                            {selectedIndent && selectedIndent.retailer_indent_items
                              ? selectedIndent.retailer_indent_items.length
                              : 0}
                          </p>
                        </div>
                        <div>
                          <p className="text-slate-500">Order Days</p>
                          <p className="font-bold text-gray-400">
                            {selectedIndent.order_days}
                          </p>
                        </div>
                        <div>
                          <p className="text-slate-500">Lead Time</p>
                          <p className="font-bold text-gray-400">
                            {selectedIndent.lead_time}
                          </p>
                        </div>
                        <div>
                          <p className="text-slate-500">Is Open</p>
                          <p className="font-bold text-gray-400 uppercase">
                            {selectedIndent.is_open}
                          </p>
                        </div>
                      </div>
                    </CardBody>
                  </Card>
                  <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                    <CardBody>
                      <div>
                        <p>INDENT VALUE</p>
                        <p>
                          {" "}
                          KES{" "}
                          {parseFloat(
                            getTotalValue(selectedIndent.retailer_indent_items)
                          ).toFixed(2)}
                        </p>
                      </div>
                    </CardBody>
                  </Card>
                  {selectedIndent &&
                    selectedIndent.retailer_indent_items &&
                    selectedIndent.retailer_indent_items.map((item) => (
                      <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                        <CardHeader className="justify-between">
                          <div className="flex gap-5 items-center mx-2 justify-between w-full">
                            <Avatar
                              className="w-20 h-20 text-large"
                              size="lg"
                              src={
                                item.images && item.images[0]
                                  ? item.images[0].image
                                  : ""
                              }
                              name={item.wholesale_receipt_title}
                            />
                            <div className="flex flex-col items-start justify-center w-full">
                              <h4 className="text-medium font-semibold leading-none text-default-600">
                                {item.wholesale_receipt_title}
                              </h4>
                              <p className="text-medium tracking-tight text-default-400">
                                {item.wholesaler_title}
                              </p>

                              <div className="flex flex-row justify-between w-full">
                                <p className="text-medium tracking-tight text-default-400">
                                  KES {item.pack_selling_price}
                                </p>
                                <p className="text-medium tracking-tight text-default-400 ">
                                  Qty Required: {item.required_quantity}
                                </p>
                                <p className="text-medium tracking-tight text-default-400 text-start ">
                                  Discount:{" "}
                                  {item.price_discount_title
                                    ? item.price_discount_title
                                    : "None"}
                                </p>
                                <p className="text-medium tracking-tight text-default-400 text-start">
                                  Net: KES {item.final_pack_price}
                                </p>
                              </div>
                              <div className="flex flex-row justify-between w-full">
                                <div className="flex flex-row justify-between">
                                  {item.days_to_expiry &&
                                    item.days_to_expiry < 90 ? (
                                    <h6 className="text-medium tracking-tight text-red-600 pr-3">
                                      Expiry Date:{" "}
                                      {item.expiry_date
                                        ? item.expiry_date
                                        : "Not Indicated"}
                                    </h6>
                                  ) : (
                                    <h6 className="text-medium tracking-tight text-green-600">
                                      Expiry Date:{" "}
                                      {item.expiry_date
                                        ? item.expiry_date
                                        : "Not indicated"}
                                    </h6>
                                  )}
                                  {item.days_to_expiry &&
                                    item.days_to_expiry < 90 ? (
                                    <h6 className="text-medium tracking-tight text-red-600 pl-3">
                                      {item.expiry_status}
                                    </h6>
                                  ) : (
                                    <h6 className="text-medium tracking-tight text-green-600">
                                      {item.expiry_status}
                                    </h6>
                                  )}
                                </div>
                                <div>
                                  <BsTrash
                                    onClick={() => handleRemoveFromIndent(item)}
                                    className="cursor-pointer hover:resize-x"
                                    size={36}
                                    color={dangerColor}
                                  />
                                </div>
                              </div>
                            </div>
                          </div>
                        </CardHeader>
                      </Card>
                    ))}

                  {selectedIndent.is_open === "true" ? (
                    <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                      <Button
                        style={{ background: currentColor, color: "white" }}
                        size="lg"
                        radius="none"
                        text="Close Indent"
                        onClick={() => handleCloseIndent()}
                        className="m-1"
                      >
                        Close Indent
                      </Button>
                    </Card>
                  ) : (
                    <div></div>
                  )}

                  <Card className="max-w-full mx-1 md:mx-5 my-2">
                    {errors && errors.length ? (
                      <div>
                        {errors.map((x) => {
                          return <p className="text-3xl text-red-500">{ }</p>;
                        })}
                    </div>
                  ) : (
                    <div></div>
                  )}
                </Card>
              </div>
            ) : (
              <div></div>
            )}
          </div>
        )}
      </div>
      <div className="col-span-1"></div>
    </div>

  );
}

export default DraftRetailerOrderCart;