import { Avatar, Button, Card, CardBody, CardHeader } from '@heroui/react'
import React from 'react'
import { AiOutlineShoppingCart } from 'react-icons/ai'
import { useStateContext } from '../../../contexts/ContextProvider'

export default function WholesalerReceiptCard({ onClick, item, selectedOrder }) {
    const { currentColor } = useStateContext()
    return (
        <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
            <CardHeader className="justify-between">
                <div className="flex gap-5 items-center mx-2 justify-between w-full">
                    <Avatar

                        isBordered
                        radius="full"
                        size="lg"
                        src={
                            item.images && item.images[0]
                                ? item.images[0].image
                                : ""
                        }
                        name={item.title}
                    />
                    <div className="flex flex-col items-start justify-center w-full">
                        <h4 className="text-medium font-semibold leading-none text-default-600">
                            {item.title}
                        </h4>

                        <div className="flex flex-row justify-between w-full">
                            <p className="text-medium tracking-tight text-default-400">
                                KES {item.pack_selling_price}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 ">
                                In Stock: {parseInt(item.pack_quantity) > 0 ? "YES" : "NO"}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 text-start ">
                                Discount:{" "}
                                {item.price_discount_title
                                    ? item.price_discount_title
                                    : "None"}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 text-start">
                                Net: KES {item.pack_selling_price_discounted}
                            </p>
                        </div>
                        {/**Expiry */}
                        <div className=" flex flex-col justify-between">

                            <div className="grid grid-cols-2 gap-3">
                                <div className="flex flex-col justify-between">
                                    {item.days_to_expiry &&
                                        item.days_to_expiry < 90 ? (
                                        <p className="text-medium tracking-tight text-red-600">
                                            <span>Expiry Date</span>
                                            <span>
                                                {item.expiry_date
                                                    ? item.expiry_date
                                                    : "Not Indicated"}
                                            </span>
                                        </p>
                                    ) : (
                                        <p className="text-medium tracking-tight text-green-600">
                                            <span>Expiry Date:</span>
                                            <span>
                                                {item.expiry_date
                                                    ? item.expiry_date
                                                    : "Not indicated"}
                                            </span>
                                        </p>
                                    )}
                                </div>
                                {item.days_to_expiry &&
                                    item.days_to_expiry < 90 ? (
                                    <p className="text-medium   text-red-600 pl-3">
                                        {item.expiry_status}
                                    </p>
                                ) : (
                                    <p className="text-medium  text-green-600">
                                        {item.expiry_status}
                                    </p>
                                )}
                                <div>



                                </div>
                            </div>
                        </div>

                    </div>
                </div>
            </CardHeader>
            <CardBody>
                {/**Dscounts */}
                <div className="grid grid-cols-2">

                    <div>
                        <p>Price Discount</p>
                        {item.wholesale_price_discount ? <div>

                            <p>Title</p>
                            <p>Till</p>
                        </div> : <div>No Price Discount</div>}
                    </div>

                    <div>
                        <p>Quantity Discount</p>
                        {item.wholesale_quantity_discount ? <div>

                            <p>Title</p>
                            <p>Till</p>
                        </div> : <div>No Quantity Discount</div>}
                    </div>
                </div>

                {/** Current Stock */}
                <div className="grid grid-cols-2">
                    <p>
                        <span className="">
                            YOUR CURRENT STOCK
                        </span>
                        <span className="ml-4">
                            {item.current_retailer_pack_quantity}{" "}
                        </span>
                    </p>
                    <p>
                        <span className="">
                            DAILY AVERAGE SALES
                        </span>
                        <span className="ml-4">
                            {parseFloat(
                                item.average_daily_consumption
                            ).toFixed(2)}
                        </span>
                    </p>
                    <p>
                        <span className="">
                            RECOMMENDED ORDER
                        </span>
                        <span className="ml-4">
                            {item.recommended_requisition_quantity}
                        </span>
                    </p>
                    <p className="grid grid-cols-2 gap-5">
                        <span className="">
                            STOCKOUTS
                        </span>
                        <span className=" ml-4">
                            {item.reported_out_of_stock}
                        </span>
                    </p>
                </div>
                <div>
                    <Button onPress={onClick} size="sm" style={{ background: currentColor, color: "white" }} title="Add to Indent" >Add to Indent</Button>
                </div>
            </CardBody>
        </Card>
    )
}
