import client from "./client";

const paymentMethodsAction = (data) => {

    return client.get("/payments/methods", data);

};
const paymentsServicesProvidersAction = (data) => {

    return client.post("/payments/providers", data);

};
const allowePaymentMethodsAction = (data) => {

    return client.post("/payments/methods/filter", data);

};

const adminPaymentsAction = (data) => {
  return client.post("/payments/admin", data);
};
const paymentAccountsAction = (data) => {
  return client.post("/payments/accounts", data);
};
export default {
  paymentMethodsAction,
  paymentsServicesProvidersAction,
  allowePaymentMethodsAction,
  adminPaymentsAction,
  paymentAccountsAction
};
